def edges_rule(g, thresh, mode='edges'):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    line=cnt.most_common(2)[1][0]; interior=cnt.most_common(1)[0][0]
    R=[r for r in range(h) if sum(x==line for x in g[r])>w/2]
    C=[c for c in range(w) if sum(g[r][c]==line for r in range(h))>h/2]
    out=[]
    for i in range(len(R)-1):
        row=[]
        for j in range(len(C)-1):
            r0,r1,c0,c1=R[i],R[i+1],C[j],C[j+1]
            if mode=='corners':
                cs=[g[r0][c0],g[r0][c1],g[r1][c0],g[r1][c1]]
                col=[x for x in cs if x!=line]
                row.append(col[0] if len(col)>=thresh and len(set(col))==1 and len(col)==len(cs) else interior)
            else:
                es=[(g[r0][c0],g[r0][c1]),(g[r1][c0],g[r1][c1]),(g[r0][c0],g[r1][c0]),(g[r0][c1],g[r1][c1])]
                cols=[]
                for a,b in es:
                    if a==b and a!=line: cols.append(a)
                cc=Counter(cols).most_common(1)
                row.append(cc[0][0] if cc and cc[0][1]>=thresh else interior)
        out.append(row)
    return out
